#!/usr/bin/env node
import './pkg-native-setup'; // MUST be first — patches Module._load before any native addon loads
import * as path from 'path';
import * as fs from 'fs';
import { spawn } from 'child_process';
import SysTray from 'systray2';
import { loadConfig } from './config/loader';
import { setDebugMode, setLogFile, log } from './logger';
import { ClickScanner } from './ble/scanner';
import { Shifter } from './gear/shifter';
import type { ButtonState } from './ble/protocol/parser';

const VERSION = '0.1.0';
const isPkg = !!(process as NodeJS.Process & { pkg?: unknown }).pkg;

// In pkg bundles, the exe directory is where side-car files (prebuilds/, traybin/) live.
// Changing CWD ensures path.join('.', 'traybin', ...) in systray2 resolves correctly.
const exeDir = isPkg ? path.dirname(process.execPath) : process.cwd();
if (isPkg) {
  process.chdir(exeDir);
  setLogFile(path.join(exeDir, 'my-zwift-click.log'));
}

function ensureConfig(): string {
  const cfgPath = path.join(exeDir, 'config.yaml');
  if (!fs.existsSync(cfgPath)) {
    const defaults = [
      '# my-zwift-click configuration',
      '# Edit this file to remap buttons or change key bindings.',
      '',
      'buttons:',
      '  gear_up: PLUS   # Button that triggers gear up (PLUS or MIN)',
      '  gear_down: MIN  # Button that triggers gear down (PLUS or MIN)',
      '',
      'mywhoosh:',
      '  gear_up_key: k  # Keyboard key sent for gear up',
      '  gear_down_key: i  # Keyboard key sent for gear down',
      '',
      'click:',
      '  scan_timeout_ms: 15000      # How long to scan before giving up (ms)',
      '  keepalive_interval_ms: 3000 # Keepalive ping interval (ms)',
      '  reconnect_delay_ms: 2000    # Delay before reconnect attempt (ms)',
      '',
      'debug: false  # Set to true for verbose logging',
    ].join('\n');
    fs.writeFileSync(cfgPath, defaults, 'utf8');
  }
  return cfgPath;
}

// 32x32 Windows ICO (DIB format): green badge, white bicycle, yellow bolt.
// Generated by scripts/gen-icon-ico.js
const ICON_BASE64 = '';

// Menu item indices
const IDX_STATUS = 0;
// IDX_SEP = 1
const IDX_EXIT = 2;

function showBalloon(title: string, text: string): void {
  const esc = (s: string) => s.replace(/[<>&'"]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;',"'":'&apos;','"':'&quot;'}[c]!));
  const xml = `<toast><visual><binding template="ToastGeneric"><text>${esc(title)}</text><text>${esc(text)}</text></binding></visual></toast>`;
  // Use PowerShell's own AUMID so unpackaged Win32 apps can send WinRT toast notifications.
  const aumid = '{1AC14E77-02E7-4E5D-B744-2EB1AE5198B7}\\WindowsPowerShell\\v1.0\\powershell.exe';
  const ps = [
    '[Windows.UI.Notifications.ToastNotificationManager,Windows.UI.Notifications,ContentType=WindowsRuntime]|Out-Null;',
    '[Windows.Data.Xml.Dom.XmlDocument,Windows.Data.Xml.Dom.XmlDocument,ContentType=WindowsRuntime]|Out-Null;',
    `$x=New-Object Windows.Data.Xml.Dom.XmlDocument;$x.LoadXml('${xml}');`,
    `$t=New-Object Windows.UI.Notifications.ToastNotification($x);`,
    `[Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier('${aumid}').Show($t)`,
  ].join('');
  spawn('powershell.exe', ['-WindowStyle', 'Hidden', '-NonInteractive', '-Command', ps], {
    detached: true, stdio: 'ignore',
  }).unref();
}

let connectedCount = 0;
let trayRef: SysTray | null = null;

function updateTrayStatus(): void {
  if (!trayRef) return;
  const title = connectedCount > 0
    ? `Connected (${connectedCount} device${connectedCount > 1 ? 's' : ''})`
    : 'Scanning for Zwift Click…';
  trayRef.sendAction({ type: 'update-item', seq_id: IDX_STATUS, item: { title, tooltip: title, enabled: false } })
    .catch(() => { /* tray may already be closing */ });
}

async function main(): Promise<void> {
  const isFirstRun = !fs.existsSync(path.join(exeDir, 'config.yaml'));
  const configPath = ensureConfig();
  if (isFirstRun) {
    spawn('cmd.exe', ['/c', 'start', '', path.join(exeDir, 'config.yaml')], {
      detached: true, stdio: 'ignore',
    }).unref();
  }
  const config = loadConfig(configPath);
  if (config.debug) setDebugMode(true);
  log.info(`my-zwift-click v${VERSION} [tray]`);
  log.info(`Config: ${configPath}`);

  const shifter = new Shifter(config);
  const handleButtons = (state: ButtonState) => shifter.handleButtonState(state);

  const scanner = new ClickScanner({
    scanTimeoutMs: config.click.scan_timeout_ms,
    reconnectDelayMs: config.click.reconnect_delay_ms,
    keepaliveMs: config.click.keepalive_interval_ms,
  });

  scanner.on('buttons', handleButtons);
  scanner.on('deviceConnected', (id: string) => {
    shifter.reset(); connectedCount++;
    log.info(`Device connected: ${id.slice(-4).toUpperCase()}`);
    updateTrayStatus();
  });
  scanner.on('deviceDisconnected', (id: string) => {
    shifter.reset(); connectedCount = Math.max(0, connectedCount - 1);
    log.warn(`Device disconnected: ${id.slice(-4).toUpperCase()}`);
    updateTrayStatus();
  });

  log.info('Initializing tray icon...');
  const tray = new SysTray({
    menu: {
      icon: ICON_BASE64,
      title: '',
      tooltip: 'my-zwift-click',
      items: [
        { title: 'Scanning for Zwift Click…', tooltip: '', enabled: false },
        SysTray.separator,
        { title: 'Exit', tooltip: 'Stop my-zwift-click', enabled: true },
      ],
    },
    debug: false,
    copyDir: true, // extract Go binary to tmpdir (required inside a pkg bundle)
  });
  trayRef = tray;

  log.info('Waiting for tray ready...');
  await tray.onClick(async (action) => {
    if (action.seq_id === IDX_EXIT) {
      log.info('Shutting down…');
      scanner.stop();
      await tray.kill(false);
      process.exit(0);
    }
  });

  // onClick resolves only after the tray is ready, so start scanning now
  tray.onError((err) => log.error(`Tray error: ${err.message}`));
  log.info('Tray icon ready — starting BLE scan');
  showBalloon('my-zwift-click', 'Running in system tray. Hold Zwift Click to connect.');
  if (isFirstRun) {
    setTimeout(() => {
      showBalloon('my-zwift-click — First Run', 'Config file created next to the app. Edit config.yaml to remap keys.');
    }, 500);
  }
  scanner.start();
}

main().catch((err: unknown) => {
  log.error(`Fatal: ${(err as Error).message}`);
  process.exit(1);
});
